#!/usr/bin/env node
/**
 * sync-claude.mjs — Sinh cấu hình Claude Code (`.claude/`) từ nguồn opencode (`.opencode/`, `skills/`).
 *
 * Nguồn sự thật DUY NHẤT vẫn là `.opencode/agent/*.md`, `.opencode/command/*.md`, `skills/<name>/SKILL.md`.
 * Script này chỉ GHI ĐÈ các file nó sinh ra (có header `generated by scripts/sync-claude.mjs`):
 *   .opencode/agent/<name>.md    → .claude/agents/<name>.md      (subagent Claude Code)
 *   .opencode/command/<name>.md  → .claude/commands/<name>.md    (slash command Claude Code)
 *   skills/<name>/SKILL.md       → .claude/skills/<name>/SKILL.md (wrapper trỏ về skills/<name>/)
 * KHÔNG đụng `.claude/settings.json`, `.claude/settings.local.json`, `.claude/hooks/`.
 *
 * CÁCH DÙNG:
 *   node scripts/sync-claude.mjs            # ghi
 *   node scripts/sync-claude.mjs --dry-run  # chỉ liệt kê
 *   node scripts/sync-claude.mjs --check    # exit 1 nếu .claude/ lệch nguồn (dùng cho CI)
 *
 * Sửa agent/command/skill → sửa ở `.opencode/` hoặc `skills/` rồi chạy lại script, ĐỪNG sửa tay `.claude/`.
 */

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const DRY_RUN = process.argv.includes('--dry-run')
const CHECK = process.argv.includes('--check')
const MARKER = 'generated by scripts/sync-claude.mjs'

// Agent read-only (chỉ ghi report scoped) → giới hạn tool. Frontmatter Claude không scope Write/Bash theo
// path/lệnh → phần đó do hook `.claude/hooks/guard.mjs` chặn theo `agent_type`.
// Agent khác để trống `tools` = kế thừa đủ tool (kể cả `Agent`, để change-request gọi builder/reviewer).
const AGENT_TOOLS = {
  reviewer: 'Read, Grep, Glob, Bash, Write',
  'spec-validator': 'Read, Grep, Glob, Bash, Write',
}

// Map khoá model trong .context/project-config.md (models:) → ghi chú trong frontmatter.
const AGENT_MODEL_KEY = {
  builder: 'models.builder',
  'builder-strong': 'models.builder_strong',
  reviewer: 'models.reviewer',
  'spec-validator': 'models.spec_validator',
  design: 'models.spec_validator',
  graph: 'models.change_request',
}

// Thay thuật ngữ riêng của opencode bằng tương đương Claude Code (chỉ áp cho file sinh ra).
const TERM_REPLACEMENTS = [
  [/`AGENTS\.md` \(luật nền\) đã được opencode \*\*nạp tự động\*\*[^\n—]*—\s*\*\*KHÔNG Read lại\*\*\./g,
    '`AGENTS.md` (luật nền) đã được nạp tự động qua `CLAUDE.md` (`@AGENTS.md`) — **KHÔNG Read lại**.'],
  [/`question` tool/g, '`AskUserQuestion` tool'],
  [/gọi tool `usage\(\)`[^;.\n]*/g, 'đọc dòng `usage:` do hook `.claude/hooks/session-handoff.mjs usage` chèn sau mỗi lần gọi subagent (không có dòng = dưới ngưỡng)'],
  [/\(gọi qua `task` tool\)/g, '(gọi qua tool `Agent`, `subagent_type: <tên>`)'],
  [/restart opencode/gi, 'chạy `node scripts/sync-claude.mjs` rồi mở session Claude Code mới'],
  [/\(`opencode\.jsonc` đặt\n/g, '(gate cứng:\n'],
  [/`permission\.task\."builder-strong": "ask"`/g, '`.claude/settings.json` → `permissions.ask: ["Agent(builder-strong)"]`'],
  [/`opencode\.jsonc` \(`permission\.bash`\)/g, '`.claude/settings.json` (`permissions.deny`)'],
]

const CLAUDE_NOTE = [
  '> **Runtime: Claude Code** — file này sinh từ `.opencode/` bởi `scripts/sync-claude.mjs`; sửa ở nguồn rồi chạy lại.',
  '> Mapping tool/agent: `CLAUDE.md` § Runtime mapping. Subagent = tool `Agent` (`subagent_type` = tên file trong `.claude/agents/`).',
  '> Gate cứng (git/DB, builder không commit, reviewer chỉ ghi report) = hook `.claude/hooks/guard.mjs` — bị chặn thì DỪNG, không thử biến thể.',
].join('\n')

function splitFrontmatter(text) {
  const normalized = text.replace(/\r\n/g, '\n')
  if (!normalized.startsWith('---\n')) return { meta: '', body: normalized }
  const end = normalized.indexOf('\n---', 4)
  if (end < 0) return { meta: '', body: normalized }
  return { meta: normalized.slice(4, end), body: normalized.slice(end + 4).replace(/^\n/, '') }
}

function readField(meta, key) {
  const m = meta.match(new RegExp(`^${key}:\\s*(.*)$`, 'm'))
  if (!m) return ''
  return m[1].trim().replace(/^["']|["']$/g, '')
}

function firstHeadingOrLine(body) {
  const line = body.split('\n').find((l) => l.trim() && !l.startsWith('>')) || ''
  return line.replace(/^#+\s*/, '').replace(/`/g, '').trim()
}

function yamlString(value) {
  return JSON.stringify(value)
}

function applyTerms(body) {
  return TERM_REPLACEMENTS.reduce((acc, [re, to]) => acc.replace(re, to), body)
}

// Đọc block `models:` trong .context/project-config.md. Chỉ nhận giá trị Claude Code hiểu được
// (alias sonnet/opus/haiku/inherit, id claude-*, hoặc anthropic/claude-* kiểu opencode → bỏ prefix);
// giá trị provider khác (openai/..., <placeholder>) → inherit vì Claude Code không chạy được.
function readClaudeModels() {
  const file = path.join(ROOT, '.context', 'project-config.md')
  if (!fs.existsSync(file)) return {}
  const models = {}
  let inBlock = false
  for (const line of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
    if (/^models:\s*$/.test(line)) { inBlock = true; continue }
    if (!inBlock) continue
    const m = line.match(/^\s+([a-z_]+):\s*([^\s#]+)/)
    if (!m) { if (line.trim() && !/^\s/.test(line)) inBlock = false; continue }
    const value = m[2].replace(/^anthropic\//, '')
    if (/^(inherit|sonnet|opus|haiku|claude-[\w.-]+)$/.test(value)) models[m[1]] = value
  }
  return models
}

const CLAUDE_MODELS = readClaudeModels()

function buildAgent(name, text) {
  const { meta, body } = splitFrontmatter(text)
  const description = readField(meta, 'description') || firstHeadingOrLine(body)
  const lines = ['---', `name: ${name}`, `description: ${yamlString(description)}`]
  if (AGENT_TOOLS[name]) lines.push(`tools: ${AGENT_TOOLS[name]}`)
  const modelKey = AGENT_MODEL_KEY[name] || (name === 'change-request' ? 'models.change_request' : '')
  lines.push(`model: ${CLAUDE_MODELS[modelKey.replace('models.', '')] || 'inherit'}`)
  if (modelKey) lines.push(`# model lấy từ ${modelKey} trong .context/project-config.md (sonnet|opus|haiku|claude-*; giá trị provider khác → inherit)`)
  lines.push(`# ${MARKER} — nguồn: .opencode/agent/${name}.md`, '---', '')

  const extra = []
  if (name === 'change-request') {
    extra.push('> **Claude Code:** gọi `builder` / `reviewer` / `spec-validator` / `spec-publisher` qua tool `Agent` (`subagent_type: <tên>`).', '')
  }
  if (name === 'reviewer' || name === 'spec-validator') {
    extra.push('> **Claude Code gate:** chỉ được `Write` vào `.context/review-reports/**` (hook guard chặn path khác); Bash chỉ dùng verify command trong',
      '> `.context/project-config.md` + `git status/diff/log/show/branch`. KHÔNG `git commit`/`push`, KHÔNG sửa source.', '')
  }
  if (name === 'builder' || name === 'builder-strong') {
    extra.push('> **Claude Code gate:** KHÔNG `git push` / `git reset --hard` / `git checkout --`. `git commit` CHỈ được khi đang ở trong worktree `.worktrees/<...>` do dispatcher giao (hook guard chặn commit ở chỗ khác).', '')
  }
  return `${lines.join('\n')}${extra.join('\n')}${applyTerms(body)}`
}

function buildCommand(name, text) {
  const { meta, body } = splitFrontmatter(text)
  const description = readField(meta, 'description') || firstHeadingOrLine(body)
  const header = ['---', `description: ${yamlString(description)}`, 'argument-hint: "[mô tả | slug | file]"',
    `# ${MARKER} — nguồn: .opencode/command/${name}.md`, '---', '', CLAUDE_NOTE, '', ''].join('\n')
  return header + applyTerms(body)
}

function buildSkill(name, text) {
  const { meta } = splitFrontmatter(text)
  const metaLines = meta.split('\n').filter((l) => /^(name|description):/.test(l))
  if (!metaLines.some((l) => l.startsWith('name:'))) metaLines.unshift(`name: ${name}`)
  return ['---', ...metaLines, `# ${MARKER} — nguồn: skills/${name}/SKILL.md`, '---', '',
    `Skill gốc nằm ở \`skills/${name}/\`. **Read \`skills/${name}/SKILL.md\`** rồi làm theo; các file tham chiếu`,
    `trong đó tính đường dẫn tương đối từ \`skills/${name}/\` (không phải từ \`.claude/skills/\`).`, ''].join('\n')
}

function collect() {
  const outputs = new Map()
  const agentDir = path.join(ROOT, '.opencode', 'agent')
  for (const file of fs.readdirSync(agentDir).filter((f) => f.endsWith('.md'))) {
    const name = file.replace(/\.md$/, '')
    outputs.set(path.join('.claude', 'agents', file), buildAgent(name, fs.readFileSync(path.join(agentDir, file), 'utf8')))
  }
  const commandDir = path.join(ROOT, '.opencode', 'command')
  for (const file of fs.readdirSync(commandDir).filter((f) => f.endsWith('.md'))) {
    const name = file.replace(/\.md$/, '')
    outputs.set(path.join('.claude', 'commands', file), buildCommand(name, fs.readFileSync(path.join(commandDir, file), 'utf8')))
  }
  const skillsDir = path.join(ROOT, 'skills')
  for (const name of fs.readdirSync(skillsDir)) {
    const skillFile = path.join(skillsDir, name, 'SKILL.md')
    if (!fs.existsSync(skillFile)) continue
    outputs.set(path.join('.claude', 'skills', name, 'SKILL.md'), buildSkill(name, fs.readFileSync(skillFile, 'utf8')))
  }
  return outputs
}

// File sinh ra trước đó mà nguồn đã bị xoá → dọn (chỉ file có MARKER).
function staleGenerated(outputs) {
  const stale = []
  for (const sub of ['agents', 'commands', 'skills']) {
    const dir = path.join(ROOT, '.claude', sub)
    if (!fs.existsSync(dir)) continue
    for (const entry of fs.readdirSync(dir, { recursive: true })) {
      const rel = path.join('.claude', sub, String(entry))
      const abs = path.join(ROOT, rel)
      if (!fs.statSync(abs).isFile() || outputs.has(rel)) continue
      if (fs.readFileSync(abs, 'utf8').includes(MARKER)) stale.push(rel)
    }
  }
  return stale
}

const outputs = collect()
const changed = [...outputs].filter(([rel, content]) => {
  const abs = path.join(ROOT, rel)
  // So bỏ qua CRLF/LF: git core.autocrlf=true checkout ra CRLF, không coi là lệch.
  return !fs.existsSync(abs) || fs.readFileSync(abs, 'utf8').replace(/\r\n/g, '\n') !== content
})
const stale = staleGenerated(outputs)

for (const [rel] of changed) console.log(`${DRY_RUN || CHECK ? 'would write' : 'write'}  ${rel.replace(/\\/g, '/')}`)
for (const rel of stale) console.log(`${DRY_RUN || CHECK ? 'would remove' : 'remove'} ${rel.replace(/\\/g, '/')}`)

if (CHECK) {
  if (changed.length || stale.length) { console.error('✗ .claude/ lệch nguồn — chạy: node scripts/sync-claude.mjs'); process.exit(1) }
  console.log('✓ .claude/ khớp nguồn')
  process.exit(0)
}
if (!DRY_RUN) {
  for (const [rel, content] of changed) {
    const abs = path.join(ROOT, rel)
    fs.mkdirSync(path.dirname(abs), { recursive: true })
    fs.writeFileSync(abs, content)
  }
  for (const rel of stale) fs.rmSync(path.join(ROOT, rel))
}
console.log(`${outputs.size} file nguồn · ${changed.length} cập nhật · ${stale.length} xoá${DRY_RUN ? ' (dry-run)' : ''}`)
